t = int(input())

def euclidean(a, b):
	(a, b) = (max(a, b), min(a, b))
	while b:
		(a, b) = (b, a % b)
	return a

def main():
	n = int(input())
	l = [int(s) for s in input().split()]
	l_next = list(range(1, n)) + [0]
	l_forw = list(range(1, n)) + [0]
	prev = n - 1
	i = 0
	res = []
	while True:
		if l_forw[i] == i:
			if l[i] == 1:
				res.append(i + 1)
			break
		if euclidean(l[i], l[l_forw[i]]) == 1:
			if l_forw[i] == l_next[i]:
				l_next[i] = l_next[l_next[i]]
			res.append(l_forw[i] + 1)
			l_forw[i] = l_forw[l_forw[i]]
			prev = i
		else:
			if prev == i:
				break
			l_next[prev] = l_next[i]
		i = l_next[prev]
	res = [len(res)] + res
	print(' '.join([str(r) for r in res]))
for _ in range(t):
	main()
